input.command:
mkdir -p scratch/soulScythe && cat > scratch/soulScythe/probe.ts <<'EOF'
import * as THREE from "three";
import build from "../../samples/soulScythe";
const root = build();
const box = new THREE.Box3().setFromObject(root, true);
let parts = 0, tris = 0;
root.traverse((o) => { if ((o as THREE.Mesh).isMesh) { parts++; const g = (o as THREE.Mesh).geometry; tris += (g.index ? g.index.count : g.attributes.position.count) / 3; } });
console.log("box", box.min.toArray().map(n=>n.toFixed(3)), box.max.toArray().map(n=>n.toFixed(3)), "parts", parts, "tris", tris);
EOF
npx tsx scratch/soulScythe/probe.ts 2>&1 | tail -20
